    if not objects:
        return [row[:] for row in grid]

    # Assign marks to their nearest piece.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            distances = [
                min(abs(r-y) + abs(c-x) for y, x in obj["cells"])
                for obj in objects
            ]
            dmin = min(distances)
            for i, d in enumerate(distances):
                if d == dmin:
                    objects[i]["marks"].append((r, c))

    n = len(objects)
    anchor = next((i for i, obj in enumerate(objects)
                   if obj["color"] == 4), 0)
    start = [None] * n
    start[anchor] = (0, 0)
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def shifted_points(obj, shift, key):
        dr, dc = shift
        return [(r + dr, c + dc) for r, c in obj[key]]

    def bounds_ok(obj, shift):
        pts = shifted_points(obj, shift, "cells") + shifted_points(obj, shift, "marks")
        return all(0 <= r < h and 0 <= c < w for r, c in pts)

    def placed_data(shifts):
        cell_owner = {}
        mark_owner = {}
        for i, shift in enumerate(shifts):
            if shift is None:
                continue
            for p in shifted_points(objects[i], shift, "cells"):
                cell_owner[p] = i
            for p in shifted_points(objects[i], shift, "marks"):
                mark_owner[p] = i
        return cell_owner, mark_owner

