        for i, shift in enumerate(shifts):
            if shift is not None:
                pts.extend(shifted_points(objects[i], shift, "cells"))
        if not pts:
            return 0
        rs = [p[0] for p in pts]
        cs = [p[1] for p in pts]
        return (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)

