        score = 0
        for i, shift in enumerate(shifts):
            if shift is None:
                continue
            for r, c in shifted_points(objects[i], shift, "marks"):
                if any(cell_owner.get((r + dy, c + dx), i) != i
                       for dy, dx in directions):
                    score += 1
        return score

