            placed_marks = list(mark_owner)

            for i in range(n):
                if shifts[i] is not None:
                    continue
                obj = objects[i]
                candidates = set()

                # Put one of this piece's marks beside an existing piece.
                for mr, mc in obj["marks"]:
                    for r, c in occupied:
                        for dy, dx in directions:
                            candidates.add((r + dy - mr, c + dx - mc))

                # Or put one of its cells beside an existing connector mark.
                for r0, c0 in obj["cells"]:
                    for mr, mc in placed_marks:
                        for dy, dx in directions:
                            candidates.add((mr + dy - r0, mc + dx - c0))

                for shift in candidates:
                    if not bounds_ok(obj, shift):
                        continue
                    newcells = shifted_points(obj, shift, "cells")
                    newmarks = shifted_points(obj, shift, "marks")
                    if any(p in occupied for p in newcells):
                        continue
                    # A connector should remain in an empty gap, not cover a piece.
                    if any(p in occupied for p in newmarks):
                        continue

                    ns = list(shifts)
                    ns[i] = shift
                    ns = tuple(ns)
                    score = connector_score(ns)
                    if ns not in next_states or score > next_states[ns]:
                        next_states[ns] = score

        if not next_states:
            break

        ranked = sorted(
            next_states.items(),
            key=lambda item: (-item[1], area(item[0]))
        )
        beam = ranked[:3000]

    complete = [(s, score) for s, score in beam if all(x is not None for x in s)]
    if complete:
        shifts, _ = min(complete, key=lambda item: (-item[1], area(item[0])))
    else:
        shifts = beam[0][0]

    out = [[0] * w for _ in range(h)]
    for i, obj in enumerate(objects):
        shift = shifts[i] if shifts[i] is not None else (0, 0)
        for r, c in shifted_points(obj, shift, "cells"):
